mapper.select:
SELECT b.id, b.dishware_id AS dishwareId, b.shop_type AS shopType, b.break_quantity AS breakQuantity, b.chargeable_quantity AS chargeableQuantity, b.unit_price AS unitPrice, b.total_price AS totalPrice, b.break_date AS breakDate, b.recorded_by AS recordedBy, i.code_number AS codeNumber, i.product_name AS productName FROM dishware_break_records b LEFT JOIN dishware_info i ON i.id = b.dishware_id WHERE 1 = 1
AND LOWER(b.shop_type) = LOWER(#{shopType})
AND b.break_date >= #{startDate}
AND b.break_date <= #{endDate}
ORDER BY b.break_date DESC, b.id DESC
